#include "config.h"
#include <assert.h>
#include <bitcoin/feerate.c>
#include <common/setup.h>
#include <stdio.h>

/* AUTOGENERATED MOCKS START */
/* AUTOGENERATED MOCKS END */

int main(int argc, const char *argv[])
{
	u32 next;

	common_setup(argv[0]);

	assert(!next_funding_feerate(0, &next));

	/* Below 24, 25/24 rounds down to the same feerate: one more. */
	assert(next_funding_feerate(1, &next) && next == 2);
	assert(next_funding_feerate(23, &next) && next == 24);

	/* From 24, 25/24 rounded down is already more. */
	assert(next_funding_feerate(24, &next) && next == 25);
	assert(next_funding_feerate(253, &next) && next == 263);
	assert(next_funding_feerate(7505, &next) && next == 7817);

	/* Largest feerate whose 25/24 still fits a u32, and the next */
	assert(next_funding_feerate(4123168604, &next) && next == 4294967295);
	next = 7;
	assert(!next_funding_feerate(4123168605, &next));
	assert(next == 7);
	assert(!next_funding_feerate(UINT32_MAX, &next));
	assert(next == 7);

	common_shutdown();
	return 0;
}
